:root {
  --bg-card: #1a0a2e;
  --bg-header: #2d1155;
  --bg-section: #120820;
  --bg-footer: #0f0618;
  --accent-yellow: #f5d800;
  --accent-pink: #ff2d78;
  --accent-cyan: #00e5ff;
  --accent-orange: #ff7a00;
  --text-primary: #ffffff;
  --text-muted: #9d7fc3;
  --ball-used: #5a3a7a;
  --ball-current: #f5d800;
  --ball-empty: #2a1545;
  --rank1-bg: #3a2800;
  --rank2-bg: #1e1e2e;
  --rank3-bg: #1a1020;
  --highlight-bg: #1a2d1a;
  --highlight-border: #00e5ff;
  --bar-track: #2d1155;
  --bar-fill: #ff2d78;
  --dot-active: #f5d800;
  --dot-inactive: #2d1155;
  --btn-bg: #ff2d78;
  --btn-text: #ffffff;
  --border-subtle: #3d1a6e;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.pinball-card {
  width: 460px;
  background: var(--bg-card);
  border-radius: 14px;
  border: 2px solid var(--accent-pink);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.card-header {
  background: var(--bg-header);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 14px;
  border-bottom: 2px solid var(--accent-yellow);
}

.header-left {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.machine-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 3px;
  color: var(--accent-cyan);
}

.machine-name {
  font-size: 18px;
  font-weight: 900;
  color: var(--accent-yellow);
  letter-spacing: 2px;
  line-height: 1.1;
}

.machine-id {
  font-size: 9px;
  color: var(--text-muted);
  letter-spacing: 1px;
}

.header-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 5px;
}

.status-badge {
  background: var(--accent-pink);
  color: var(--text-primary);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 2px;
  padding: 2px 7px;
  border-radius: 20px;
}

.ball-count {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 3px;
}

.ball-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--text-muted);
}

.balls {
  display: flex;
  gap: 4px;
}

.ball {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--ball-empty);
  border: 1px solid var(--border-subtle);
}

.ball.used {
  background: var(--ball-used);
}

.ball.current {
  background: var(--ball-current);
  border-color: var(--accent-yellow);
}

.score-section {
  display: flex;
  background: var(--bg-section);
  border-bottom: 1px solid var(--border-subtle);
}

.current-score-block {
  flex: 1;
  padding: 8px 14px;
  border-right: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.score-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--text-muted);
}

.score-value {
  font-size: 22px;
  font-weight: 900;
  color: var(--accent-cyan);
  letter-spacing: 1px;
  line-height: 1;
}

.score-bar-track {
  height: 4px;
  background: var(--bar-track);
  border-radius: 2px;
  overflow: hidden;
}

.score-bar-fill {
  height: 100%;
  width: 58%;
  background: var(--bar-fill);
  border-radius: 2px;
}

.multiplier-block {
  padding: 8px 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-width: 80px;
}

.mult-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--text-muted);
}

.mult-value {
  font-size: 24px;
  font-weight: 900;
  color: var(--accent-orange);
  line-height: 1;
}

.mult-dots {
  display: flex;
  gap: 3px;
}

.dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--dot-inactive);
}

.dot.active {
  background: var(--dot-active);
}

.leaderboard {
  padding: 7px 14px;
  background: var(--bg-section);
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.lb-title {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 3px;
  color: var(--accent-pink);
}

.lb-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.lb-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 7px;
  border-radius: 5px;
  background: var(--rank3-bg);
  border: 1px solid transparent;
}

.lb-row.rank-1 {
  background: var(--rank1-bg);
  border-color: var(--accent-yellow);
}

.lb-row.rank-2 {
  background: var(--rank2-bg);
  border-color: var(--border-subtle);
}

.lb-row.highlight {
  background: var(--highlight-bg);
  border-color: var(--highlight-border);
}

.rank {
  font-size: 9px;
  font-weight: 800;
  color: var(--accent-yellow);
  min-width: 26px;
}

.lb-row.rank-2 .rank {
  color: var(--text-muted);
}

.lb-row.rank-3 .rank {
  color: var(--accent-orange);
}

.lb-row.highlight .rank {
  color: var(--accent-cyan);
}

.player {
  font-size: 11px;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: 1px;
  flex: 1;
}

.lb-score {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-primary);
}

.lb-date {
  font-size: 9px;
  color: var(--text-muted);
  min-width: 32px;
  text-align: right;
}

.card-footer {
  background: var(--bg-footer);
  padding: 7px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.bonus-chip {
  font-size: 9px;
  font-weight: 800;
  color: var(--accent-yellow);
  background: var(--rank1-bg);
  border: 1px solid var(--accent-yellow);
  border-radius: 20px;
  padding: 3px 8px;
  letter-spacing: 1px;
  white-space: nowrap;
}

.footer-info {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  flex: 1;
}

.location {
  font-size: 9px;
  color: var(--text-muted);
}

.date {
  font-size: 9px;
  font-weight: 700;
  color: var(--accent-cyan);
  letter-spacing: 1px;
}

.play-btn {
  background: var(--btn-bg);
  color: var(--btn-text);
  border: none;
  border-radius: 7px;
  padding: 6px 12px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
  cursor: pointer;
  white-space: nowrap;
}
